def minCost(grid):
    m, n = len(grid), len(grid[0])

    # prev[j] = set of all XOR values of paths reaching cell (i-1, j)
    prev = [set() for _ in range(n)]

    for i in range(m):
        cur = [None] * n
        for j in range(n):
            # Collect all XOR values that can arrive at (i, j) before including its value
            if i == 0 and j == 0:
                src = {0}
            else:
                src = set()
                if i > 0:
                    src |= prev[j]       # coming from above
                if j > 0:
                    src |= cur[j - 1]    # coming from the left
            v = grid[i][j]
            # Include this cell's value in every path XOR
            cur[j] = {x ^ v for x in src}
        prev = cur

    # Best answer is the smallest reachable XOR at the bottom-right cell
    return min(prev[n - 1])
